export type ModalSize = ComponentSize | 'xl' | 'fullscreen';

/**
 * Modal fullscreen breakpoint variants
 * Only applies when size is 'fullscreen'
 *
 * @see https://getbootstrap.com/docs/5.3/components/modal/#fullscreen-modal
