  /**
   * ARIA role for the modal dialog.
   * Use 'alertdialog' for confirmation/destructive dialogs that require
   * user acknowledgment (WCAG: alerts the user).
   * @default 'dialog'
   */
  role?: 'dialog' | 'alertdialog';
}

